import { fireEvent, render, screen } from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import { describe, expect, it, vi } from 'vitest'
import { KeyboardControls } from './KeyboardControls'

// Independently transcribed from the user's image, not generated by the binding implementation.
const pictured = [
  ['1',"S'"], ['2','E'], ['5','M'], ['6','M'], ['9',"E'"], ['0','S'],
  ['q',"z'"], ['w','B'], ['e',"L'"], ['r',"Lw'"], ['t','x'], ['y','x'], ['u','Rw'], ['i','R'], ['o',"B'"], ['p','z'],
  ['a',"y'"], ['s','D'], ['d','L'], ['f',"U'"], ['g',"F'"], ['h','F'], ['j','U'], ['k',"R'"], ['l',"D'"], [';','y'],
  ['z','Dw'], ['x',"M'"], ['c',"Uw'"], ['v','Lw'], ['b',"x'"], ['n',"x'"], ['m',"Rw'"], [',','Uw'], ['.',"M'"], ['/',"Dw'"],
]
function setup(disabled = false) {
  const onMove = vi.fn(), onUndo = vi.fn(), onRedo = vi.fn()
  const view = render(<KeyboardControls disabled={disabled} suffix="2" onMove={onMove} onUndo={onUndo} onRedo={onRedo} />)
  return { ...view, onMove, onUndo, onRedo }
}
describe('pictured reference mapping', () => {
  it.each(pictured)('key %s dispatches exactly %s independent of button suffix', (key, word) => {
    const { onMove } = setup()
    fireEvent.keyDown(window, { key })
    expect(onMove).toHaveBeenCalledExactlyOnceWith(word)
  })
  it('uses physical key positions and Shift does not alter explicit moves', () => {
    const { onMove } = setup()
    fireEvent.keyDown(window, { key: 'a', code: 'KeyQ', shiftKey: true })
    fireEvent.keyDown(window, { key: ':', code: 'Semicolon', shiftKey: true })
    expect(onMove.mock.calls).toEqual([["z'"], ['y']])
  })
  it('handles rapid layer selections synchronously and resets with Space', () => {
    const { onMove } = setup()
    fireEvent.keyDown(window, { key: '4', code: 'Digit4' })
    fireEvent.keyDown(window, { key: 'd', code: 'KeyD' })
    fireEvent.keyDown(window, { key: 'r', code: 'KeyR' })
    fireEvent.keyDown(window, { key: '7', code: 'Digit7' })
    fireEvent.keyDown(window, { key: 'i', code: 'KeyI' })
    fireEvent.keyDown(window, { key: 'u', code: 'KeyU' })
    fireEvent.keyDown(window, { key: ' ', code: 'Space' })
    fireEvent.keyDown(window, { key: 'i', code: 'KeyI' })
    expect(onMove.mock.calls).toEqual([['Lw'], ['x'], ['Rw'], ['x'], ['R']])
    expect(screen.getByRole('button', { name: 'Key I: R' })).toBeVisible()
  })
  it('3 and 8 reduce widths without executing a cube action', () => {
    const { onMove } = setup()
    for (const key of ['4','7','3','8']) fireEvent.keyDown(window,{key})
    expect(onMove).not.toHaveBeenCalled()
    expect(screen.getByRole('button', { name: 'Key D: L' })).toBeVisible()
    expect(screen.getByRole('button', { name: 'Key I: R' })).toBeVisible()
  })
  it('ignores held keys, modifiers, composition, unmapped keys, and input fields', () => {
    const { onMove } = setup()
    for (const patch of [{ repeat: true }, { altKey: true }, { ctrlKey: true }, { metaKey: true }, { isComposing: true }]) fireEvent.keyDown(window,{key:'i',code:'KeyI',...patch})
    fireEvent.keyDown(window,{key:'Escape',code:'Escape'})
    for (const tag of ['input','textarea','select']) { const element = document.createElement(tag); document.body.append(element); fireEvent.keyDown(element,{key:'i',code:'KeyI'}); element.remove() }
    const editable=document.createElement('div'); editable.contentEditable='true'; editable.setAttribute('contenteditable','true'); document.body.append(editable); fireEvent.keyDown(editable,{key:'i',code:'KeyI'}); editable.remove()
    expect(onMove).not.toHaveBeenCalled()
  })
  it('allows opt-out and leaves native form undo alone', async () => {
    const { onMove, onUndo, onRedo } = setup(), user = userEvent.setup()
    fireEvent.keyDown(window,{key:'z',ctrlKey:true}); fireEvent.keyDown(window,{key:'z',metaKey:true,shiftKey:true})
    expect(onUndo).toHaveBeenCalledTimes(1); expect(onRedo).toHaveBeenCalledTimes(1)
    await user.click(screen.getByLabelText('Enable keyboard shortcuts'))
    fireEvent.keyDown(window,{key:'i',code:'KeyI'})
    expect(onMove).not.toHaveBeenCalled()
    await user.click(screen.getByRole('button',{name:'Key I: R'}))
    expect(onMove).toHaveBeenCalledExactlyOnceWith('R')
  })
  it('does not intercept Space on a focused button', () => {
    const { onMove } = setup()
    const event = new KeyboardEvent('keydown',{key:' ',code:'Space',bubbles:true,cancelable:true})
    screen.getByRole('button',{name:'Key I: R'}).dispatchEvent(event)
    expect(event.defaultPrevented).toBe(false)
    expect(onMove).not.toHaveBeenCalled()
  })
  it('suppresses move input and disables key buttons while loading or solving', () => {
    const { onMove } = setup(true)
    fireEvent.keyDown(window,{key:'i',code:'KeyI'})
    expect(onMove).not.toHaveBeenCalled()
    expect(screen.getByRole('button',{name:'Key I: R'})).toBeDisabled()
  })
  it('keeps face-letter shortcuts as an explicit alternative', async () => {
    const { onMove } = setup(), user=userEvent.setup()
    await user.selectOptions(screen.getByLabelText('Keyboard layout'),'face-letters')
    fireEvent.keyDown(window,{key:'R',shiftKey:true}); fireEvent.keyDown(window,{key:'r'})
    expect(onMove.mock.calls).toEqual([["R'"],['R2']])
  })
})
